  3	final class BellmanFord {
  4	    private static final int INF = 100_000_000;
  5	    private static final int NEGATIVE_CYCLE_MARKER = -1;
  6	    private static final int FROM_INDEX = 0;
  7	    private static final int TO_INDEX = 1;
  8	    private static final int WEIGHT_INDEX = 2;
  9	    private static final int EDGE_FIELD_COUNT = 3;
 10	
 11	    private BellmanFord() {
 12	    }
 13	
 14	    static int[] bellmanFord(int vertexCount, int[][] edgeData, int source) {
 15	        Graph graph = Graph.from(vertexCount, edgeData);
 16	        graph.validateSource(source);
 17	        return shortestPathsFrom(graph, source).toArray();
 18	    }
 19	
 20	    private static ShortestPathResult shortestPathsFrom(Graph graph, int source) {
 21	        Distances distances = graph.initialDistances(source);
 22	
 23	        for (int pass = 0; pass < graph.relaxationPasses(); pass++) {
 24	            if (!graph.relaxEdges(distances)) {
 25	                break;
 26	            }
 27	        }
 28	
 29	        if (graph.hasReachableNegativeCycle(distances)) {
 30	            return ShortestPathResult.negativeCycle();
 31	        }
 32	
 33	        return ShortestPathResult.distances(distances);
 34	    }
 35	
 36	    private static String formatDistances(int[] distances) {
 37	        StringBuilder output = new StringBuilder();
 38	        for (int distance : distances) {
 39	            output.append(distance).append(' ');
 40	        }
 41	
 42	        return output.toString();
 43	    }
 44	
 45	    private static final class Edge {
 46	        private final int from;
 47	        private final int to;
 48	        private final int weight;
 49	
 50	        private Edge(int from, int to, int weight) {
 51	            this.from = from;
 52	            this.to = to;
 53	            this.weight = weight;
 54	        }
 55	
 56	        private boolean isWithin(int vertexCount) {
 57	            return from >= 0 && from < vertexCount && to >= 0 && to < vertexCount;
 58	        }
 59	
 60	        private boolean relax(Distances distances) {
 61	            return distances.relax(from, to, weight);
 62	        }
 63	
 64	        private boolean canRelax(Distances distances) {
 65	            return distances.canRelax(from, to, weight);
 66	        }
 67	    }
 68	
 69	    private static final class Distances {
 70	        private final int[] values;
 71	
 72	        private Distances(int vertexCount, int source) {
 73	            values = new int[vertexCount];
 74	            Arrays.fill(values, INF);
 75	            values[source] = 0;
 76	        }
 77	
 78	        private boolean relax(int from, int to, int weight) {
 79	            if (!canRelax(from, to, weight)) {
 80	                return false;
 81	            }
 82	
 83	            values[to] = values[from] + weight;
 84	            return true;
 85	        }
 86	
 87	        private boolean canRelax(int from, int to, int weight) {
 88	            return values[from] != INF && values[from] + weight < values[to];
 89	        }
 90	
 91	        private int[] toArray() {
 92	            return Arrays.copyOf(values, values.length);
 93	        }
 94	    }
 95	
 96	    private static final class ShortestPathResult {
 97	        private final Distances distances;
 98	        private final boolean hasNegativeCycle;
 99	
100	        private ShortestPathResult(Distances distances, boolean hasNegativeCycle) {
101	            this.distances = distances;
102	            this.hasNegativeCycle = hasNegativeCycle;
103	        }
104	
105	        private static ShortestPathResult distances(Distances distances) {
106	            return new ShortestPathResult(distances, false);
107	        }
108	
109	        private static ShortestPathResult negativeCycle() {
110	            return new ShortestPathResult(null, true);
111	        }
112	
113	        private int[] toArray() {
114	            if (hasNegativeCycle) {
115	                return new int[]{NEGATIVE_CYCLE_MARKER};
116	            }
117	
118	            return distances.toArray();
119	        }
120	    }
121	
122	    private static final class Graph {
123	        private final int vertexCount;
124	        private final Edge[] edges;
125	
126	        private Graph(int vertexCount, Edge[] edges) {
127	            this.vertexCount = vertexCount;
128	            this.edges = edges;
129	        }
130	
131	        private static Graph from(int vertexCount, int[][] edgeData) {
132	            if (vertexCount < 0) {
133	                throw new IllegalArgumentException("Vertex count cannot be negative");
134	            }
135	
136	            if (edgeData == null) {
137	                throw new IllegalArgumentException("Edges cannot be null");
138	            }
139	
140	            Edge[] edges = new Edge[edgeData.length];
141	            for (int i = 0; i < edgeData.length; i++) {
142	                edges[i] = parseEdge(vertexCount, edgeData[i], i);
143	            }
144	
145	            return new Graph(vertexCount, edges);
146	        }
147	
148	        private static Edge parseEdge(int vertexCount, int[] edgeData, int index) {
149	            if (edgeData == null || edgeData.length != EDGE_FIELD_COUNT) {
150	                throw new IllegalArgumentException("Edge " + index + " must contain from, to, and weight");
151	            }
152	
153	            Edge edge = new Edge(edgeData[FROM_INDEX], edgeData[TO_INDEX], edgeData[WEIGHT_INDEX]);
154	            if (!edge.isWithin(vertexCount)) {
155	                throw new IllegalArgumentException("Edge " + index + " references a vertex outside the graph");
156	            }
157	
158	            return edge;
159	        }
160	
161	        private void validateSource(int source) {
162	            if (source < 0 || source >= vertexCount) {
163	                throw new IllegalArgumentException("Source vertex is out of range");
164	            }
165	        }
166	
167	        private Distances initialDistances(int source) {
168	            return new Distances(vertexCount, source);
169	        }
170	
171	        private int relaxationPasses() {
172	            return Math.max(0, vertexCount - 1);
173	        }
174	
175	        private boolean relaxEdges(Distances distances) {
176	            boolean changed = false;
177	
178	            for (Edge edge : edges) {
179	                if (edge.relax(distances)) {
180	                    changed = true;
181	                }
182	            }
183	
184	            return changed;
185	        }
186	
187	        private boolean hasReachableNegativeCycle(Distances distances) {
188	            for (Edge edge : edges) {
189	                if (edge.canRelax(distances)) {
190	                    return true;
191	                }
192	            }
193	
194	            return false;
195	        }
196	    }
197	
198	    public static void main(String[] args) {
199	
200	        int vertexCount = 5;
201	
202	        int[][] edges = new int[][] {
203	            {1, 3, 2},
204	            {4, 3, -1},
205	            {2, 4, 1},
206	            {1, 2, 1},
207	            {0, 1, 5}
208	        };
209	
210	        int source = 0;
211	
212	        int[] distances = bellmanFord(vertexCount, edges, source);
213	
214	        System.out.print(formatDistances(distances));
215	    }
216	}

